 "content": "from collections import Counter, deque


def transform(grid):
    """Fill background components enclosed by the non-background linework."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == bg:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not touches_edge:
                for y, x in cells:
                    out[y][x] = 4
    return out


