    # The repeated frame color is the foreground; all other cells form the fillable background.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    visited = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in visited:
                continue
            q = deque([(r, c)])
            visited.add((r, c))
            component = []
            edge = False
            while q:
                y, x = q.popleft()
                component.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in visited and grid[ny][nx] == bg:
                        visited.add((ny, nx))
                        q.append((ny, nx))
            if not edge:
                for y, x in component:
                    out[y][x] = 4
    return out


if __name__ == '__main__':
